async function searchBookPages(bookId,question,limit=8){const q=[...new Set(words(question).map(normalize).filter(x=>x.length>1))],best=[];const d=await db();return await new Promise((resolve,reject)=>{const t=d.transaction('pages','readonly'),req=t.objectStore('pages').index('byBook').openCursor(IDBKeyRange.only(bookId));req.onsuccess=()=>{const c=req.result;if(!c)return resolve(best.sort((a,b)=>b.score-a.score||a.page-b.page));const p=c.value;if(p.text&&!p.missing){const txt=normalize(p.text),score=q.reduce((n,w)=>n+(txt.includes(w)?1:0),0)+(p.title&&q.some(w=>normalize(p.title).includes(w))?2:0);if(score>0||best.length<limit){best.push({...p,score});best.sort((a,b)=>b.score-a.score||a.page-b.page);if(best.length>limit)best.length=limit}}c.continue()};req.onerror=()=>reject(req.error)})}
