/* ───────── Piper Worker ───────── */
let piperWorker, piperSeq=0;const piperPending=new Map();
function ensurePiper(){if(piperWorker)return piperWorker;piperWorker=new Worker('/piper-worker.js?v=24',{type:'module'});piperWorker.onmessage=e=>{const m=e.data||{},p=piperPending.get(m.id);if(!p)return;if(m.progress){p.progress?.(m);return}piperPending.delete(m.id);m.ok?p.resolve(m):p.reject(new Error(m.error||'piper_failed'))};piperWorker.onerror=()=>{for(const p of piperPending.values())p.reject(new Error('تعذر تحميل Piper. اتصل بالإنترنت مرة واحدة لتجهيز المحرك.'));piperPending.clear()};return piperWorker;}
function piperCall(action,data={},progress){return new Promise((resolve,reject)=>{const id=`p${++piperSeq}`;piperPending.set(id,{resolve,reject,progress});ensurePiper().postMessage({id,action,...data})})}
async function preparePiper(statusEl=one('#smartPiperStatus')){statusEl.textContent='يتم تنزيل/فحص Piper ونموذج Arabic Kareem…';try{const r=await piperCall('prepare',{},m=>{statusEl.textContent=`تنزيل Piper: ${m.percent||0}%${m.url?' · '+m.url.split('/').pop():''}`});statusEl.textContent=r.stored?.includes('ar_JO-kareem-medium')?'Piper جاهز للعمل بدون إنترنت ✓':'تم تجهيز Piper.';return true}catch(e){statusEl.textContent=`تعذر تجهيز Piper: ${e.message}`;statusEl.classList.add('error');return false}}
async function piperBlob(text){const key=`piper:${hash(text)}`;const cached=await get('audio',key).catch(()=>null);if(cached?.blob)return cached.blob;const r=await piperCall('speak',{text});const blob=r.blob instanceof Blob?r.blob:new Blob([r.blob],{type:'audio/wav'});await put('audio',{id:key,blob,provider:'piper',createdAt:Date.now(),textHash:hash(text)});return blob;}

/* ───────── unified audio / read any text ───────── */
const narrator=one('#smartNarratorAudio');let readMode='book',readToken=0,bookAudioContext=null,blobFinish=null;const bookSources=new Set();
function narration(active){window.MafateehMixer?.setNarrationActive?.(active);window.dispatchEvent(new CustomEvent('mafateeh:narration',{detail:{active,source:'smart'}}));}
function stopRead(){readToken++;blobFinish?.();blobFinish=null;narrator.pause();narrator.removeAttribute('src');narrator.load();for(const src of [...bookSources]){try{src.stop()}catch(_){}}bookSources.clear();if(bookAudioContext){try{bookAudioContext.close()}catch(_){}bookAudioContext=null}narration(false);one('#smartReadStatus').textContent='تم الإيقاف.';one('#smartReadProgress').style.width='0%'}
narrator.onplaying=()=>narration(true);narrator.onpause=()=>narration(false);narrator.onended=()=>narration(false);
many('#smartReadModes .smart-mode').forEach(b=>b.onclick=()=>{readMode=b.dataset.mode;many('#smartReadModes .smart-mode').forEach(x=>x.classList.toggle('on',x===b));one('#smartBookFallback').style.display=readMode==='book'?'':'none'});
async function cloudBlob(text,provider,voice=one('#smartVoice').value){const key=`${provider}:${voice}:${hash(text)}`;const cached=await get('audio',key).catch(()=>null);if(cached?.blob)return cached.blob;const r=await fetch('/api/ai/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider,text,voice})});if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||`TTS ${r.status}`)}const blob=await r.blob();await put('audio',{id:key,blob,provider,createdAt:Date.now(),textHash:hash(text)});return blob;}
async function playBlob(blob,token=readToken){if(token!==readToken)return;const url=URL.createObjectURL(blob);narrator.src=url;narrator.volume=Math.max(0,Math.min(1,window.MafateehMixer?.getNarratorVolume?.()??1));await narrator.play();await new Promise((resolve,reject)=>{let done=false;const finish=()=>{if(done)return;done=true;blobFinish=null;URL.revokeObjectURL(url);narration(false);resolve()};blobFinish=finish;narrator.onended=finish;narrator.onerror=()=>{if(done)return;done=true;blobFinish=null;URL.revokeObjectURL(url);reject(new Error('تعذر تشغيل الصوت'))}})}

let bookWordData=null;
function chapterVisibleText(c){return [c.title,c.key,...(c.body||[]).map(x=>x[1]),c.idea,c.apply,...(c.qs||[]),c.week].filter(Boolean)}
function bookIndex(){if(bookWordData)return bookWordData;const chapters=CH.map((c,chapterIndex)=>{const raw=chapterVisibleText(c).flatMap(t=>[...String(t).matchAll(/\S+/gu)].filter(m=>/[\p{L}\p{N}]/u.test(m[0])).map(m=>m[0]));return {chapterIndex,raw,norm:raw.map(normalize)}});const map=new Map();chapters.forEach(ch=>ch.norm.forEach((w,i)=>{if(!w)return;const arr=map.get(w)||[];arr.push([ch.chapterIndex,i]);map.set(w,arr)}));bookWordData={chapters,map};return bookWordData;}
function planBookVoice(text){const toks=words(text),norms=toks.map(normalize),data=bookIndex(),segments=[];let i=0,covered=0;while(i<norms.length){const candidates=data.map.get(norms[i])||[];let best=null;for(const [ci,wi] of candidates.slice(0,80)){const ch=data.chapters[ci];let len=1;while(len<12&&i+len<norms.length&&wi+len<ch.norm.length&&norms[i+len]===ch.norm[wi+len])len++;if(!best||len>best.len)best={type:'book',ci,wi,len,text:toks.slice(i,i+len).join(' ')}}if(best){segments.push(best);covered+=best.len;i+=best.len}else{let j=i+1;while(j<norms.length&&!data.map.has(norms[j]))j++;segments.push({type:'fallback',text:toks.slice(i,j).join(' '),len:j-i});i=j}}return {segments,total:toks.length,covered,coverage:toks.length?Math.round(covered*100/toks.length):0}}
const timingCache=new Map(),bufferCache=new Map();
async function timing(ci){if(timingCache.has(ci))return timingCache.get(ci);const r=await fetch(`/audio/timings/chapter-${String(CH[ci].no).padStart(2,'0')}.json?v=1`);if(!r.ok)throw new Error('تعذر تحميل توقيتات صوت الراوي');const j=await r.json();timingCache.set(ci,j);return j}
async function chapterBuffer(ci,ctx){if(bufferCache.has(ci))return bufferCache.get(ci);const r=await fetch(`/audio/chapter-${String(CH[ci].no).padStart(2,'0')}.mp3`);if(!r.ok)throw new Error('تعذر تحميل صوت الفصل');const b=await ctx.decodeAudioData(await r.arrayBuffer());bufferCache.set(ci,b);while(bufferCache.size>4)bufferCache.delete(bufferCache.keys().next().value);return b}
function playBufferSegment(ctx,buffer,start,duration,token){return new Promise((resolve,reject)=>{if(token!==readToken)return resolve();const src=ctx.createBufferSource(),gain=ctx.createGain();gain.gain.value=Math.max(0,Math.min(1,window.MafateehMixer?.getNarratorVolume?.()??1));src.buffer=buffer;src.connect(gain).connect(ctx.destination);bookSources.add(src);src.onended=()=>{bookSources.delete(src);resolve()};try{src.start(0,Math.max(0,start),Math.max(.04,duration));narration(true)}catch(e){bookSources.delete(src);reject(e)}})}
async function playBookVoice(text,token){const plan=planBookVoice(text);one('#smartReadStatus').textContent=`تغطية صوت الراوي: ${plan.coverage}% · ${plan.covered}/${plan.total} كلمة. الباقي سيستخدم ${one('#smartBookFallback').value}.`;if(!plan.total)throw new Error('اكتب نصًا أولًا');const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw new Error('Web Audio غير مدعوم');bookAudioContext=new Context();if(bookAudioContext.state==='suspended')await bookAudioContext.resume();for(let si=0;si<plan.segments.length;si++){if(token!==readToken)break;const seg=plan.segments[si];one('#smartReadProgress').style.width=`${Math.round(si*100/plan.segments.length)}%`;if(seg.type==='book'){const t=await timing(seg.ci),first=t.words?.[seg.wi],last=t.words?.[seg.wi+seg.len-1];if(!first||!last)continue;const b=await chapterBuffer(seg.ci,bookAudioContext);await playBufferSegment(bookAudioContext,b,Math.max(0,first[0]-.025),Math.max(.05,last[1]-first[0]+.05),token)}else{const fallback=one('#smartBookFallback').value;let blob;if(fallback==='piper')blob=await piperBlob(seg.text);else blob=await cloudBlob(seg.text,fallback);if(token!==readToken)break;const arr=await blob.arrayBuffer(),buf=await bookAudioContext.decodeAudioData(arr.slice(0));await playBufferSegment(bookAudioContext,buf,0,buf.duration,token)}}narration(false);one('#smartReadProgress').style.width='100%';return plan}
async function readAnyText(text,mode=readMode){const value=String(text||'').trim();if(!value){one('#smartReadStatus').textContent='اكتب نصًا أولًا.';return}stopRead();const token=++readToken;one('#smartReadStatus').classList.remove('error');one('#smartReadStatus').textContent='يتم تجهيز الصوت…';try{if(mode==='book'){await playBookVoice(value,token)}else{const chunks=textChunks(value),label=mode==='piper'?'Piper':mode==='gemini'?'Gemini':'OpenAI';for(let i=0;i<chunks.length;i++){if(token!==readToken)return;one('#smartReadStatus').textContent=`${label}: تجهيز مقطع ${i+1}/${chunks.length}…`;one('#smartReadProgress').style.width=`${Math.round(i*100/chunks.length)}%`;const blob=mode==='piper'?await piperBlob(chunks[i]):await cloudBlob(chunks[i],mode);if(token!==readToken)return;await playBlob(blob,token)}one('#smartReadProgress').style.width='100%';one('#smartReadStatus').textContent=mode==='piper'?'Piper: تم التشغيل محليًا وحفظ المقاطع ✓':`تم إنشاء الصوت عبر ${label} وحفظ المقاطع محليًا ✓`}if(token===readToken)one('#smartReadStatus').textContent+=' ✓'}catch(e){if(token!==readToken)return;one('#smartReadStatus').textContent=`تعذر القراءة: ${e.message}`;one('#smartReadStatus').classList.add('error');narration(false)}}
one('#smartSpeak').onclick=()=>readAnyText(one('#smartReadText').value);one('#smartStop').onclick=stopRead;one('#smartPreparePiper').onclick=()=>preparePiper(one('#smartReadStatus'));
async function checkEngines(){const st=one('#smartReadStatus'),items=[];st.classList.remove('error');st.textContent='يتم فحص المحركات…';try{const h=await fetch('/api/ai/status').then(r=>r.json());items.push(`Gemini: ${h.gemini?.configured?'جاهز':'يحتاج API key'}`,`OpenAI: ${h.openai?.configured?'جاهز':'يحتاج API key'}`)}catch(_){items.push('Cloud API: تعذر الفحص')}try{const r=await fetch('/audio/chapter-01.mp3',{method:'HEAD',cache:'no-store'});items.push(`صوت الراوي: ${r.ok?'جاهز':'ملفات MP3 غير موجودة على الاستضافة'}`)}catch(_){items.push('صوت الراوي: تعذر الفحص')}try{const p=await piperCall('status');items.push(`Piper: ${p.stored?.includes('ar_JO-kareem-medium')?'Offline جاهز':'يحتاج تنزيل أول مرة'}`)}catch(_){items.push('Piper: يحتاج اتصالًا أوليًا لتحميل Runtime')}st.textContent=items.join(' · ')}
one('#smartCheckEngines').onclick=checkEngines;
window.MafateehSmartReader={read:readAnyText,stop:stopRead,planBookVoice,preparePiper};

/* ───────── Smart PDF Library v24 — no fixed book-size/page cap ───────── */
let activeBookId=null, readerChapter=0, importCancel=false, generateCancel=false,voiceBankCancel=false;
const IMPORT_BATCH=20, PDF_PART_TARGET_PAGES=180, PDF_PART_MAX_BYTES=44*1024*1024, MAX_READER_UNIT_PAGES=80, IMPORT_STAGES=['upload','analyze','extract','format','intelligence','audio','offline'];
let pdfLibPromise=null;
async function ensurePdfLib(){
  if(window.PDFLib?.PDFDocument)return window.PDFLib;
  if(pdfLibPromise)return pdfLibPromise;
  pdfLibPromise=new Promise((resolve,reject)=>{const old=document.querySelector('script[data-mafateeh-pdf-lib]');if(old){old.addEventListener('load',()=>window.PDFLib?.PDFDocument?resolve(window.PDFLib):reject(new Error('تعذر تشغيل مقسّم PDF')),{once:true});old.addEventListener('error',()=>reject(new Error('تعذر تحميل مقسّم PDF')),{once:true});return}const sc=document.createElement('script');sc.src='https://unpkg.com/pdf-lib@1.17.1/dist/pdf-lib.min.js';sc.async=true;sc.dataset.mafateehPdfLib='1';sc.onload=()=>window.PDFLib?.PDFDocument?resolve(window.PDFLib):reject(new Error('تعذر تشغيل مقسّم PDF'));sc.onerror=()=>reject(new Error('تعذر تحميل مكتبة تقسيم PDF. يلزم اتصال بالإنترنت عند تحويل الكتب الكبيرة لأول مرة.'));document.head.appendChild(sc)}).catch(e=>{pdfLibPromise=null;throw e});
  return pdfLibPromise;
}
async function openPdfSource(file){const lib=await ensurePdfLib();let bytes;try{bytes=await file.arrayBuffer()}catch(_){throw new Error('تعذر قراءة ملف PDF من الجهاز. أعد اختيار الملف.')}try{return await lib.PDFDocument.load(bytes,{updateMetadata:false})}catch(e){if(String(e?.message||'').toLowerCase().includes('encrypt'))throw new Error('الكتاب PDF محمي/مشفّر ولا يمكن تقسيمه تلقائيًا. افتح نسخة غير مشفرة.');throw new Error('تعذر فتح بنية PDF: '+(e?.message||'ملف غير صالح'))}}
async function makePdfPart(sourceDoc,startPage,endHint,baseName){const lib=await ensurePdfLib();let end=Math.max(startPage,endHint);for(;;){const out=await lib.PDFDocument.create(),idx=[];for(let p=startPage-1;p<end;p++)idx.push(p);const copied=await out.copyPages(sourceDoc,idx);copied.forEach(pg=>out.addPage(pg));const bytes=await out.save({useObjectStreams:true,addDefaultPage:false,objectsPerTick:40});if(bytes.byteLength<=PDF_PART_MAX_BYTES||end===startPage){if(bytes.byteLength>PDF_PART_MAX_BYTES)throw new Error(`صفحة ${startPage} وحدها أكبر من سعة الدفعة السحابية. الكتاب نفسه بلا حد ثابت، لكن هذه الصفحة تحتاج ضغطًا/إعادة حفظ قبل تحليلها.`);const name=`${String(baseName||'book').replace(/\.pdf$/i,'')}.part-${startPage}-${end}.pdf`;return {file:new File([bytes],name,{type:'application/pdf'}),startPage,endPage:end,pageCount:end-startPage+1,size:bytes.byteLength}}end=startPage+Math.max(1,Math.floor((end-startPage+1)/2))-1}}
async function bookList(){return (await all('books').catch(()=>[])).sort((a,b)=>(b.updatedAt||b.importedAt||0)-(a.updatedAt||a.importedAt||0))}
async function saveBook(book){book.updatedAt=Date.now();await put('books',book);return book}
function status(el,text,error=false){el.textContent=text;el.classList.toggle('error',error)}
function pipeline(stage,state='active'){const root=one('#smartImportPipeline');if(!root)return;const idx=IMPORT_STAGES.indexOf(stage);many('[data-stage]',root).forEach((el,i)=>{el.classList.toggle('done',i<idx||(state==='done'&&i===idx));el.classList.toggle('active',i===idx&&state!=='done');el.classList.toggle('error',i===idx&&state==='error')})}
function pipelineReset(){many('[data-stage]',one('#smartImportPipeline')).forEach(el=>el.classList.remove('done','active','error'));one('#smartImportProgress').style.width='0%'}
function importPercent(stage,within=0){const idx=Math.max(0,IMPORT_STAGES.indexOf(stage));return Math.min(100,Math.round((idx+Math.max(0,Math.min(1,within)))*100/IMPORT_STAGES.length))}
async function requestPersistentStorage(){try{if(navigator.storage?.persist){const persisted=await navigator.storage.persist();return !!persisted}}catch(_){}return false}
async function apiPdf(payload,{retries=4}={}){let last;for(let attempt=0;attempt<=retries;attempt++){try{const r=await fetch('/api/ai/pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await r.json().catch(()=>({}));if(r.ok)return j;const err=new Error(j.error||`PDF ${r.status}`);err.status=r.status;if(![429,502,503,504].includes(r.status)||attempt===retries)throw err;last=err}catch(e){last=e;if(attempt===retries)throw e}await sleep(Math.min(16000,1000*2**attempt+Math.random()*650))}throw last||new Error('pdf_failed')}
async function uploadPdf(file){const form=new FormData();form.set('action','upload');form.set('file',file);let last;for(let attempt=0;attempt<5;attempt++){const r=await fetch('/api/ai/pdf',{method:'POST',body:form});const j=await r.json().catch(()=>({}));if(r.ok)return j;last=new Error(j.error||`Upload ${r.status}`);last.status=r.status;if(![429,502,503,504].includes(r.status))throw last;await sleep(Math.min(16000,1200*2**attempt))}throw last||new Error('upload_failed')}
async function deleteRemote(remote){const name=remote?.name;if(!name)return;try{await apiPdf({action:'delete',fileName:name},{retries:1})}catch(_){}}
function extractedPageCount(book){const imported=Number(book?.import?.lastPage||0),processed=Math.max(0,imported||(book?.conversionComplete?Number(book?.pageCount||0):0));return Math.max(0,processed-(book?.missingPages||[]).filter(n=>+n<=processed).length)}
function normalizeChapters(book){const max=Math.max(1,+book.pageCount||1);let chapters=Array.isArray(book.chapters)?book.chapters.filter(c=>c&&c.title):[];chapters=chapters.map((c,i)=>({title:String(c.title||`الفصل ${i+1}`),startPage:Math.max(1,Math.min(max,+c.startPage||1)),endPage:Math.max(1,Math.min(max,+c.endPage||(+c.startPage||1))),key:String(c.key||''),summary:String(c.summary||''),idea:String(c.idea||''),apply:String(c.apply||''),questions:Array.isArray(c.questions)?c.questions.slice(0,6).map(String):[]})).sort((a,b)=>a.startPage-b.startPage);for(let i=0;i<chapters.length;i++){if(chapters[i].endPage<chapters[i].startPage)chapters[i].endPage=chapters[i].startPage;if(i<chapters.length-1&&chapters[i].endPage>=chapters[i+1].startPage)chapters[i].endPage=Math.max(chapters[i].startPage,chapters[i+1].startPage-1)}if(!chapters.length){chapters=[];for(let p=1,part=1;p<=max;p+=MAX_READER_UNIT_PAGES,part++)chapters.push({title:max>MAX_READER_UNIT_PAGES?`الكتاب — جزء ${part}`:'الكتاب',startPage:p,endPage:Math.min(max,p+MAX_READER_UNIT_PAGES-1),key:'',summary:book.summary||'',idea:'',apply:'',questions:[]})}const units=[];for(const c of chapters){const span=c.endPage-c.startPage+1;if(span<=MAX_READER_UNIT_PAGES){units.push(c);continue}let part=1;for(let p=c.startPage;p<=c.endPage;p+=MAX_READER_UNIT_PAGES,part++)units.push({...c,title:`${c.title} — جزء ${part}`,startPage:p,endPage:Math.min(c.endPage,p+MAX_READER_UNIT_PAGES-1),key:part===1?c.key:'',idea:part===1?c.idea:'',apply:part===1?c.apply:'',questions:part===1?c.questions:[]})}book.chapters=units;return book}
function mergePartAnalysis(book,analysis,offset,partStart,partEnd){if(!analysis)return;const first=partStart===1;if(first||!book.title)book.title=analysis.title||book.title;if(first||!book.author)book.author=analysis.author||book.author||'';if(first||!book.language)book.language=analysis.language||book.language||'ar';if(analysis.summary){book.analysisSummaries=book.analysisSummaries||[];if(!book.analysisSummaries.some(x=>x.startPage===partStart))book.analysisSummaries.push({startPage:partStart,endPage:partEnd,text:String(analysis.summary)})}const incoming=(analysis.chapters||[]).map(c=>({...c,startPage:Math.max(partStart,offset+(+c.startPage||1)),endPage:Math.min(partEnd,offset+(+c.endPage||(+c.startPage||1)))})).filter(c=>c.title&&c.startPage<=c.endPage);const existing=Array.isArray(book.chapters)?book.chapters:[];for(const c of incoming){if(!existing.some(x=>x.title===c.title&&Math.abs((+x.startPage||0)-c.startPage)<=1))existing.push(c)}book.chapters=existing;book.themes=[...new Set([...(book.themes||[]),...(analysis.themes||[]).map(String)])];book.warnings=[...(book.warnings||[]),...(analysis.warnings||[]).map(String)]}
function localBookDigest(book){const sums=(book.analysisSummaries||[]).sort((a,b)=>a.startPage-b.startPage),chapters=book.chapters||[];return {executiveSummary:sums.map(x=>x.text).filter(Boolean).join(' ').slice(0,24000)||book.summary||'',keyIdeas:chapters.filter(c=>c.idea||c.key).map(c=>({idea:c.idea||c.key,pages:[c.startPage]})),concepts:(book.themes||[]).map(name=>({name,explanation:'مفهوم متكرر رصده Gemini أثناء تحليل أجزاء الكتاب.',pages:[]})),actionPoints:chapters.filter(c=>c.apply).map(c=>c.apply),questions:chapters.flatMap(c=>c.questions||[]),quotes:[]}}
async function prepareImportAudio(book,provider,count=3){if(provider==='none')return {done:0};await ensurePagedBook(book);if(provider==='piper'){const ok=await preparePiper(one('#smartImportStatus'));if(!ok)throw new Error('تعذر تجهيز Piper الآن؛ الكتاب نفسه تم تحويله ويمكن تجهيز الصوت لاحقًا.')}const available=await firstTextPages(book.id,count);let done=0;for(const page of available){if(importCancel)throw new Error('تم إيقاف الاستيراد');const id=`bookaudio:${book.id}:${page.page}:${provider}`;if(!(await get('audio',id).catch(()=>null))){const chunks=textChunks(page.text,provider==='openai'?3600:2600),blobs=[];for(const chunk of chunks){if(importCancel)throw new Error('تم إيقاف الاستيراد');blobs.push(provider==='piper'?await piperBlob(chunk):await cloudBlob(chunk,provider))}await put('audio',{id,bookId:book.id,page:page.page,provider,blob:blobs[0]||null,blobs,parts:blobs.length,createdAt:Date.now()})}done++}return {done}}
