async function resumeBook(id){const book=await get('books',id);if(!book)return;activeBookId=id;openHub('library');pipelineReset();try{await continueBookImport(book)}catch(_){}}
async function renderBooks(){const books=await bookList(),root=one('#smartBookList');root.innerHTML=books.length?books.map(b=>{const pct=Math.round(extractedPageCount(b)*100/Math.max(1,b.pageCount||1)),state=b.import?.state||'ready',stateText=state==='ready'?'جاهز ✓':state==='paused'?'متوقف مؤقتًا':state==='error'?'يحتاج استكمال':'يتم التحويل';return `<article class="smart-book-item ${state!=='ready'?'processing':''}"><div><h4>${esc(b.title)}</h4><p>${esc(b.author||'بدون مؤلف')} · ${b.pageCount||b.pages?.length||0} صفحة · ${pct}% مستخرج · <strong>${stateText}</strong></p>${state!=='ready'?`<div class="smart-mini-progress"><i style="width:${pct}%"></i></div>`:''}</div><div class="smart-book-actions">${state!=='ready'?`<button data-resume-book="${b.id}" title="استكمال التحويل">↻</button>`:''}<button data-open-book="${b.id}" title="فتح">📖</button><button data-ai-book="${b.id}" title="افهم كتابي">🧠</button><button data-del-book="${b.id}" title="حذف">🗑</button></div></article>`}).join(''):'<p class="smart-muted">لا توجد كتب بعد. اضغط «اختر ملف PDF» وابدأ التحويل الذكي.</p>';many('[data-resume-book]',root).forEach(b=>b.onclick=()=>resumeBook(b.dataset.resumeBook));many('[data-open-book]',root).forEach(b=>b.onclick=()=>openBook(b.dataset.openBook));many('[data-ai-book]',root).forEach(b=>b.onclick=()=>{activeBookId=b.dataset.aiBook;openHub('bookai')});many('[data-del-book]',root).forEach(b=>b.onclick=async()=>{const id=b.dataset.delBook;if(!confirm('حذف هذا الكتاب وكل الصوت المحفوظ له؟'))return;await del('books',id);await del('files',id);await deleteBookPages(id);await deleteBookAudio(id);if(activeBookId===id)activeBookId=null;renderBooks();refreshBookAI()});await populateBookSelects(books)}
async function populateBookSelects(books){if(!books)books=await bookList();for(const id of ['smartAiBook','smartOfflineBook']){const s=one('#'+id);if(!s)continue;const old=s.value||activeBookId;s.innerHTML=books.length?books.map(b=>`<option value="${b.id}">${esc(b.title)}</option>`).join(''):'<option value="">لا توجد كتب</option>';if(books.some(b=>b.id===old))s.value=old}if(!activeBookId&&books[0])activeBookId=books[0].id}

/* ───────── Imported book reader ───────── */
async function openBook(id,chapterIndex=null){let book=await get('books',id);if(!book)return;book=await ensurePagedBook(book);activeBookId=id;readerChapter=chapterIndex==null?(book.progress?.chapter||0):chapterIndex;bookShade.classList.add('on');bookShade.setAttribute('aria-hidden','false');bodyLock(true);await renderBookReader(book)}
function closeBook(){bookShade.classList.remove('on');bookShade.setAttribute('aria-hidden','true');if(!hub.classList.contains('on'))bodyLock(false)}
one('#smartReaderClose').onclick=closeBook;bookShade.onclick=e=>{if(e.target===bookShade)closeBook()};
async function renderBookReader(book){if(!book)book=await get('books',activeBookId);if(!book)return;book=await ensurePagedBook(book);const chapters=book.chapters?.length?book.chapters:[{title:'الكتاب',startPage:1,endPage:Math.min(book.pageCount||1,MAX_READER_UNIT_PAGES),key:'',summary:'',idea:'',apply:'',questions:[]}];readerChapter=Math.max(0,Math.min(chapters.length-1,readerChapter));const ch=chapters[readerChapter],pages=await bookPageRange(book.id,+ch.startPage||1,+ch.endPage||book.pageCount||1);one('#smartReaderTitle').textContent=book.title;one('#smartReaderMeta').textContent=`${book.author||'بدون مؤلف'} · الوحدة ${readerChapter+1}/${chapters.length} · ص ${ch.startPage||1}–${ch.endPage||book.pageCount}`;const select=one('#smartReaderChapter');select.innerHTML=chapters.map((c,i)=>`<option value="${i}"${i===readerChapter?' selected':''}>${i+1}. ${esc(c.title||`الفصل ${i+1}`)}</option>`).join('');one('#smartReaderPrev').disabled=readerChapter<=0;one('#smartReaderNext').disabled=readerChapter>=chapters.length-1;one('#smartReaderContent').innerHTML=`<h1>${esc(ch.title||book.title)}</h1><div class="book-meta">${esc(book.title)} · ${esc(book.author||'')}</div>${ch.key?`<div class="book-box"><b>🔑 مفتاح الفصل — مولّد بالذكاء الاصطناعي</b>${esc(ch.key)}</div>`:''}${pages.length?pages.map(p=>`<section><div class="smart-page-no">صفحة ${p.page}${p.title?' · '+esc(p.title):''}</div>${String(p.text||'').split(/\n{2,}/).filter(Boolean).map(x=>`<p>${esc(x).replace(/\n/g,'<br>')}</p>`).join('')}</section>`).join(''):'<p class="smart-warning">هذه الصفحات لم تُستخرج بعد. استكمل تحويل الكتاب من المكتبة.</p>'}${ch.idea?`<div class="book-box"><b>💡 الفكرة الأساسية — AI</b>${esc(ch.idea)}</div>`:''}${ch.apply?`<div class="book-box"><b>✓ تطبيق عملي — AI</b>${esc(ch.apply)}</div>`:''}${ch.questions?.length?`<div class="book-box"><b>؟ أسئلة للتفكير — AI</b>${ch.questions.map(q=>`<div>• ${esc(q)}</div>`).join('')}</div>`:''}`;book.progress={...(book.progress||{}),chapter:readerChapter};await saveBook(book)}
one('#smartReaderChapter').onchange=async e=>{readerChapter=+e.target.value;renderBookReader()};one('#smartReaderPrev').onclick=()=>{readerChapter--;renderBookReader()};one('#smartReaderNext').onclick=()=>{readerChapter++;renderBookReader()};
one('#smartReaderListen').onclick=async()=>{let book=await get('books',activeBookId);book=await ensurePagedBook(book);const ch=book?.chapters?.[readerChapter]||{startPage:1,endPage:Math.min(book?.pageCount||1,MAX_READER_UNIT_PAGES)},pages=book?await bookPageRange(book.id,ch.startPage,ch.endPage):[],text=pages.map(p=>p.text).join('\n\n');openHub('read');one('#smartReadText').value=text;readMode='piper';many('#smartReadModes .smart-mode').forEach(b=>b.classList.toggle('on',b.dataset.mode==='piper'));readAnyText(one('#smartReadText').value,'piper')};
one('#smartReaderAsk').onclick=()=>{closeBook();openHub('bookai')};one('#smartReaderPdf').onclick=async()=>{const f=await get('files',activeBookId);if(!f?.blob)return status(one('#smartBookAiStatus'),'نسخة PDF الأصلية غير موجودة على الجهاز.',true);const url=URL.createObjectURL(f.blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)};

/* ───────── Book AI / Retrieval ───────── */
async function retrievePages(book,question,limit=8){await ensurePagedBook(book);return searchBookPages(book.id,question,limit)}
function renderMessages(root,history){root.innerHTML=(history||[]).map(m=>`<div class="smart-msg ${m.role==='user'?'me':''}">${esc(m.content)}${m.refs?.length?`<small>المراجع: ${m.refs.map(x=>'ص. '+x).join('، ')}</small>`:''}</div>`).join('')||'<p class="smart-muted">ابدأ بسؤال عن هذا الكتاب.</p>';root.scrollTop=root.scrollHeight}
async function refreshBookAI(){const books=await bookList();await populateBookSelects(books);const select=one('#smartAiBook');if(activeBookId&&books.some(b=>b.id===activeBookId))select.value=activeBookId;activeBookId=select.value||activeBookId;let book=activeBookId?await get('books',activeBookId):null;if(book)book=await ensurePagedBook(book);if(!book){one('#smartBookChat').innerHTML='<p class="smart-muted">أضف كتاب PDF أولًا.</p>';one('#smartBookIntel').innerHTML='';one('#smartBookDigest').textContent='';return}renderMessages(one('#smartBookChat'),book.aiHistory||[]);const stats=await bookPageStats(book.id),wordCount=stats.wordCount,audio=await countBookAudio(book.id);one('#smartBookIntel').innerHTML=`<div class="smart-stat"><b>${book.pageCount||stats.total}</b><small>صفحة</small></div><div class="smart-stat"><b>${book.chapters?.length||1}</b><small>فصل/وحدة</small></div><div class="smart-stat"><b>${wordCount.toLocaleString('ar')}</b><small>كلمة مستخرجة</small></div><div class="smart-stat"><b>${audio}</b><small>مقطع صوت Offline</small></div><div class="smart-stat"><b>${book.aiHistory?.filter(x=>x.role==='user').length||0}</b><small>سؤال للكتاب</small></div><div class="smart-stat"><b>${Math.round(extractedPageCount(book)*100/Math.max(1,book.pageCount||1))}%</b><small>اكتمال الاستخراج</small></div>`;const d=book.digest;one('#smartBookDigest').innerHTML=d?`<strong>الملخص التنفيذي:</strong> ${esc(d.executiveSummary||book.summary||'')}<br><br>${(d.keyIdeas||[]).slice(0,6).map(x=>`• ${esc(x.idea)} <span class="smart-source">${x.pages?.length?'ص. '+x.pages.join('، '):''}</span>`).join('<br>')}`:esc(book.summary||'لم يتم إنشاء لوحة عميقة بعد.');}
one('#smartAiBook').onchange=e=>{activeBookId=e.target.value;refreshBookAI()};many('[data-book-q]').forEach(b=>b.onclick=()=>{one('#smartBookQuestion').value=b.dataset.bookQ;one('#smartAskBook').click()});
one('#smartAskBook').onclick=async()=>{const q=one('#smartBookQuestion').value.trim(),st=one('#smartBookAiStatus');if(!q||!activeBookId)return;const book=await get('books',activeBookId);if(!book)return;const refs=await retrievePages(book,q);const context=refs.map(p=>`[ص. ${p.page}]\n${p.text.slice(0,5500)}`).join('\n\n');book.aiHistory=[...(book.aiHistory||[]),{role:'user',content:q,at:Date.now()}].slice(-30);await saveBook(book);renderMessages(one('#smartBookChat'),book.aiHistory);one('#smartBookQuestion').value='';status(st,'Gemini يراجع صفحات الكتاب الأكثر صلة…');try{const r=await fetch('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:'gemini',system:`أنت «افهم كتابي» داخل مفاتيح الثروة. أجب فقط اعتمادًا على مقتطفات الكتاب المرفقة. ضع مراجع الصفحات بصيغة [ص. N] بعد كل معلومة مهمة. إذا لم تجد الإجابة قل بوضوح إنها غير موجودة في الصفحات المسترجعة.\n\nمقتطفات الكتاب:\n${context}`,messages:[{role:'user',content:q}]})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Book AI failed');const cited=[...j.text.matchAll(/\[ص\.\s*(\d+)\]/g)].map(m=>+m[1]);book.aiHistory.push({role:'assistant',content:j.text,refs:[...new Set(cited)],at:Date.now()});await saveBook(book);renderMessages(one('#smartBookChat'),book.aiHistory);status(st,`تمت الإجابة من ${refs.length} صفحات مرجعية ✓`)}catch(e){status(st,`تعذر السؤال: ${e.message}`,true)}};

/* ───────── Generic AI assistant ───────── */
let assistantHistory=JSON.parse(localStorage.getItem('mafateehAssistantHistory')||'[]');
function renderAssistant(){renderMessages(one('#smartAssistantChat'),assistantHistory)}
async function sendAssistant(){const input=one('#smartAssistantInput'),text=input.value.trim();if(!text)return;assistantHistory.push({role:'user',content:text});assistantHistory=assistantHistory.slice(-30);input.value='';renderAssistant();status(one('#smartAssistantStatus'),'يتم إرسال السؤال…');try{const provider=one('#smartAssistantProvider').value,r=await fetch('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider,messages:assistantHistory})}),j=await r.json();if(!r.ok)throw new Error(j.error||`AI ${r.status}`);assistantHistory.push({role:'assistant',content:j.text});assistantHistory=assistantHistory.slice(-30);localStorage.setItem('mafateehAssistantHistory',JSON.stringify(assistantHistory));renderAssistant();status(one('#smartAssistantStatus'),`تم الرد عبر ${provider==='gemini'?'Gemini':'OpenAI'} ✓`)}catch(e){status(one('#smartAssistantStatus'),`تعذر المساعد: ${e.message}`,true)}}
one('#smartAssistantSend').onclick=sendAssistant;one('#smartAssistantInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendAssistant()}});one('#smartClearAssistant').onclick=()=>{assistantHistory=[];localStorage.removeItem('mafateehAssistantHistory');renderAssistant()};one('#smartReadLastReply').onclick=()=>{const last=[...assistantHistory].reverse().find(x=>x.role==='assistant');if(!last)return;openHub('read');one('#smartReadText').value=last.content;readAnyText(last.content,'piper')};
function openProvider(provider){const native=window.webkit?.messageHandlers?.mafateehNative;if(native){native.postMessage({action:'openProvider',provider,prompt:''});return}window.open(provider==='openai'?'https://chatgpt.com/':'https://gemini.google.com/','_blank','noopener,noreferrer')}
one('#smartOpenGemini').onclick=()=>openProvider('gemini');one('#smartOpenChatGPT').onclick=()=>openProvider('openai');

/* ───────── Offline / pregeneration ───────── */
async function piperStatus(){const el=one('#smartPiperStatus');try{const r=await piperCall('status');el.classList.remove('error');el.textContent=r.stored?.includes('ar_JO-kareem-medium')?'Arabic Kareem موجود محليًا ✓':'النموذج غير محمّل بعد.'}catch(e){status(el,`Piper يحتاج اتصالًا أوليًا لتحميل Runtime: ${e.message}`,true)}}
one('#smartOfflinePiper').onclick=()=>preparePiper();one('#smartRemovePiper').onclick=async()=>{try{await piperCall('remove');piperStatus()}catch(e){status(one('#smartPiperStatus'),e.message,true)}};
async function downloadVoiceBank(){voiceBankCancel=false;one('#smartVoiceBankCancel').disabled=false;one('#smartVoiceBankDownload').disabled=true;const st=one('#smartVoiceBankStatus'),bar=one('#smartVoiceBankProgress'),cache=await caches.open('mafateeh-narrator-bank-v22'),urls=[];for(let i=0;i<CH.length;i++){const n=String(CH[i].no).padStart(2,'0');urls.push(`/audio/chapter-${n}.mp3`,`/audio/timings/chapter-${n}.json?v=1`)}try{for(let i=0;i<urls.length;i++){if(voiceBankCancel)throw new Error('stopped');const url=urls[i];if(!(await cache.match(url))){const r=await fetch(url);if(!r.ok)throw new Error(`فشل ${url}`);await cache.put(url,r.clone())}const pct=Math.round((i+1)*100/urls.length);bar.style.width=pct+'%';st.textContent=`تنزيل بنك صوت الراوي ${pct}% · ${i+1}/${urls.length}`}st.textContent='تم تنزيل بنك صوت الراوي بالكامل للعمل Offline ✓'}catch(e){st.textContent=e.message==='stopped'?'تم إيقاف التنزيل ويمكن استكماله لاحقًا.':`خطأ: ${e.message}${String(e.message||'').includes('/audio/chapter-')?' · ملفات MP3 غير موجودة على الاستضافة؛ شغّل scripts/download-deployed-audio.sh قبل النشر الكامل.':''}`}finally{one('#smartVoiceBankCancel').disabled=true;one('#smartVoiceBankDownload').disabled=false}}
one('#smartVoiceBankDownload').onclick=downloadVoiceBank;one('#smartVoiceBankCancel').onclick=()=>{voiceBankCancel=true};
async function generatePageAudio(){const book=await get('books',one('#smartOfflineBook').value),provider=one('#smartOfflineProvider').value,st=one('#smartGenerateStatus'),bar=one('#smartGenerateProgress');if(!book)return status(st,'اختر كتابًا أولًا.',true);const from=Math.max(1,+one('#smartPageFrom').value||1),maxPage=Math.max(1,+book.pageCount||Number.MAX_SAFE_INTEGER),to=Math.min(maxPage,Math.max(from,+one('#smartPageTo').value||from));generateCancel=false;one('#smartGenerateCancel').disabled=false;one('#smartGeneratePages').disabled=true;let done=0,total=to-from+1;try{for(let p=from;p<=to;p++){if(generateCancel)throw new Error('stopped');const page=await bookPageGet(book.id,p);if(!page?.text){done++;continue}const id=`bookaudio:${book.id}:${p}:${provider}`;if(!(await get('audio',id).catch(()=>null))){const chunks=textChunks(page.text),blobs=[];for(const chunk of chunks){blobs.push(provider==='piper'?await piperBlob(chunk):await cloudBlob(chunk,provider))}await put('audio',{id,bookId:book.id,page:p,provider,blob:blobs[0]||null,blobs,parts:blobs.length,createdAt:Date.now()})}done++;const pct=Math.round(done*100/total);bar.style.width=pct+'%';st.textContent=`تم تجهيز صفحة ${p} · ${pct}%`}st.textContent=`تم حفظ صوت الصفحات ${from}–${to} للعمل دون إنترنت ✓`}catch(e){st.textContent=e.message==='stopped'?'تم إيقاف التوليد. المحفوظ يظل موجودًا.':`خطأ: ${e.message}`}finally{one('#smartGenerateCancel').disabled=true;one('#smartGeneratePages').disabled=false;refreshStorage()}}
one('#smartGeneratePages').onclick=generatePageAudio;one('#smartGenerateCancel').onclick=()=>{generateCancel=true};
async function refreshStorage(){const audioCount=await countStore('audio').catch(()=>0),books=await bookList(),stats=one('#smartStorageStats');let estimate={};try{estimate=await navigator.storage?.estimate?.()||{}}catch(_){}stats.innerHTML=`<div class="smart-stat"><b>${books.length}</b><small>كتاب PDF</small></div><div class="smart-stat"><b>${audioCount}</b><small>ملف صوت مولد</small></div><div class="smart-stat"><b>${estimate.usage?formatBytes(estimate.usage):'—'}</b><small>استخدام التخزين</small></div>`}
async function refreshOffline(){await populateBookSelects();piperStatus();refreshStorage();const cache=await caches.open('mafateeh-narrator-bank-v22').catch(()=>null);let count=0;if(cache){for(let i=0;i<CH.length;i++){const n=String(CH[i].no).padStart(2,'0');if(await cache.match(`/audio/chapter-${n}.mp3`))count++}}one('#smartVoiceBankStatus').textContent=count===CH.length?'بنك صوت الراوي كامل Offline ✓':`${count}/${CH.length} فصل محفوظ حاليًا.`}
async function refreshAll(){renderAssistant();await renderBooks();if(activeBookId)await refreshBookAI().catch(()=>{});fetch('/api/ai/status').then(r=>r.json()).then(j=>{if(j.gemini?.configured===false)one('#smartImportStatus').textContent='Gemini API غير مفعّل على الخادم بعد. ضع GEMINI_API_KEY ثم أعد المحاولة.'}).catch(()=>{})}

/* media session for smart narrator */
try{if('mediaSession'in navigator){narrator.addEventListener('playing',()=>{navigator.mediaSession.metadata=new MediaMetadata({title:'مفاتيح الثروة — اقرأ أي نص',artist:'القارئ الذكي'});navigator.mediaSession.playbackState='playing'});narrator.addEventListener('pause',()=>navigator.mediaSession.playbackState='paused');navigator.mediaSession.setActionHandler('play',()=>narrator.play());navigator.mediaSession.setActionHandler('pause',()=>narrator.pause());navigator.mediaSession.setActionHandler('stop',stopRead)}}catch(_){}

window.MafateehSmartLibrary={open:openHub,openBook,refresh:refreshAll,addBook:()=>openHub('library'),resume:resumeBook};
refreshAll();
